import{_ as e,C as n,o as l,c as s,a2 as o,b as a,w as r,a as g,E as d,a3 as E}from"./chunks/framework.BBdhqAg0.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",x=JSON.parse('{"title":"영업 조직 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/organization.md","filePath":"sales/organization.md","lastUpdated":1793417412000}'),B={name:"sales/organization.md"};function C(c,t,u,h,_,b){const i=n("Mermaid");return l(),s("div",null,[t[1]||(t[1]=o('<h1 id="영업-조직-관리" tabindex="-1">영업 조직 관리 <a class="header-anchor" href="#영업-조직-관리" aria-label="Permalink to &quot;영업 조직 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="영업 조직 계층 트리 및 인력 명부 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/organization.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>영업 조직 관리</strong> 페이지는 프로젝트에 투입되는 분양 대행사, 영업 본부/팀, 그리고 영업 상담사 및 팀장 등 영업 인력을 3단계 계층 구조로 등록하고, 계좌 정보, 3.3% 프리랜서 과세 유형, 그리고 필수 증빙 서류(등본, 통장 사본, 신분증, 위촉계약서 등)를 체계적으로 관리하는 기준 정보 센터입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [분양 대행 관리] → [영업 조직 관리]**를 선택하여 접속합니다.</li></ul>',4)),(l(),a(E,null,{default:r(()=>[d(i,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%F0%9F%8F%A2%201.%20%EB%B6%84%EC%96%91%20%EB%8C%80%ED%96%89%EC%82%AC%20(Agency)%3Cbr%3E(%EB%B3%B8%EC%82%AC%20%EC%A7%81%EC%98%81%20%EC%82%AC%EC%97%85%EB%B6%80%20%EB%98%90%EB%8A%94%20%EC%99%B8%EC%A3%BC%20%EB%8C%80%ED%96%89%EC%82%AC)%22%5D%20--%3E%20B%5B%22%F0%9F%91%A5%202.%20%EC%98%81%EC%97%85%20%EB%B3%B8%EB%B6%80%20%EB%B0%8F%20%ED%8C%80%20(Team)%3Cbr%3E(%EB%B3%B8%EB%B6%80%EC%9E%A5%C2%B7%ED%8C%80%EC%9E%A5%20%EC%A7%81%EB%AC%B4%20%EB%B0%B0%EC%A0%95)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%A7%91%E2%80%8D%F0%9F%92%BC%203.%20%EC%98%81%EC%97%85%20%EC%9D%B8%EB%A0%A5%20(Person)%3Cbr%3E(%EB%B6%84%EC%96%91%20%EC%83%81%EB%8B%B4%EC%82%AC%20%EB%93%B1%EB%A1%9D%20%26%20%EA%B3%84%EC%A2%8C%20%EA%B4%80%EB%A6%AC)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%93%91%20%EC%A6%9D%EB%B9%99%20%EC%84%9C%EB%A5%98%20%EC%A0%91%EC%88%98%20%26%20%EA%B4%80%EB%A6%AC%EC%9E%90%20%EA%B2%80%EC%A6%9D%3Cbr%3E(%EB%93%B1%EB%B3%B8%C2%B7%ED%86%B5%EC%9E%A5%EC%82%AC%EB%B3%B8%C2%B7%EC%8B%A0%EB%B6%84%EC%A6%9D%C2%B7%EC%9C%84%EC%B4%89%EA%B3%84%EC%95%BD%EC%84%9C)%22%5D%0A%20%20%20%20C%20--%3E%20E%5B%22%F0%9F%93%8A%20%EA%B3%84%EC%95%BD%20%EC%8B%A4%EC%A0%81%20%EB%A7%A4%ED%95%91%20%26%20%EC%88%98%EC%88%98%EB%A3%8C%20%EC%A0%95%EC%82%B0%20%EC%97%B0%EB%8F%99%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[g(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<h2 id="_1-개요-및-3단계-조직-아키텍처" tabindex="-1">1. 개요 및 3단계 조직 아키텍처 <a class="header-anchor" href="#_1-개요-및-3단계-조직-아키텍처" aria-label="Permalink to &quot;1. 개요 및 3단계 조직 아키텍처&quot;">​</a></h2><p>분양 영업을 전담하는 조직 체계를 체계적으로 전산화합니다.</p><ul><li><strong>1단계: 분양 대행사</strong>: 최상위 조직 단위로, 본사 직영 사업부 또는 외부 전문 분양대행사를 등록합니다.</li><li><strong>2단계: 영업 본부 및 팀</strong>: 대행사 산하의 영업 본부 및 실무 팀을 계층형 트리로 구성합니다.</li><li><strong>3단계: 영업 인력</strong>: 각 팀에 소속되는 상담사, 팀장, 본부장을 등록하고, 수수료 입금 계좌 및 과세 유형(3.3% 프리랜서)을 관리합니다.</li><li><strong>증빙 서류 검증 체계</strong>: 수수료 정산 및 금융 이체를 위해 법적으로 필수적인 증빙 서류(등본, 통장 사본, 신분증 사본, 위촉계약서, 보안서약서 등)의 파일 업로드 및 관리자 검증을 지원합니다.</li></ul><h2 id="_2-주요-기능" tabindex="-1">2. 주요 기능 <a class="header-anchor" href="#_2-주요-기능" aria-label="Permalink to &quot;2. 주요 기능&quot;">​</a></h2><ul><li><strong>3단계 영업 조직 계층 관리</strong>: 대행사 ➔ 영업 본부/팀 ➔ 영업 인력(상담사)</li><li><strong>좌측 조직 트리뷰 연동</strong>: 대행사 또는 팀 클릭 시 우측 명부에 해당 소속 인력만 즉시 필터링</li><li><strong>대행사 운영 형태 구분</strong>: 본사 직영 분양팀 또는 외부 전문 분양대행사 구분 관리</li><li><strong>프리랜서(3.3%) 세무 유형 설정</strong>: 사업소득세 원천징수 대상자 등록</li><li><strong>정산 입금 계좌 관리</strong>: 주요 시중은행, 인터넷전문은행, 지방은행 셀렉터 및 계좌번호, 예금주 등록</li><li><strong>증빙 서류 접수 및 검증 체계</strong>: 주민등록등본, 통장 사본, 신분증, 영업 위촉계약서, 보안서약서 파일 업로드 및 관리자 검증</li><li><strong>모바일 서류 열람 및 공유</strong>: 스마트폰 모바일 앱에서 상담사별 제출 서류 확인, PDF/이미지 즉시 열람 및 카카오톡/이메일 공유 지원</li><li><strong>재직 상태 관리</strong>: 위촉(재직), 휴직, 해촉(퇴사) 상태 관리</li></ul><h2 id="_3-화면-구성-및-조작-가이드" tabindex="-1">3. 화면 구성 및 조작 가이드 <a class="header-anchor" href="#_3-화면-구성-및-조작-가이드" aria-label="Permalink to &quot;3. 화면 구성 및 조작 가이드&quot;">​</a></h2><h3 id="_1-좌측-영업-조직-계층-트리뷰" tabindex="-1">1. 좌측 영업 조직 계층 트리뷰 <a class="header-anchor" href="#_1-좌측-영업-조직-계층-트리뷰" aria-label="Permalink to &quot;1. 좌측 영업 조직 계층 트리뷰&quot;">​</a></h3><p>프로젝트에 등록된 대행사와 산하 팀 구조를 한눈에 볼 수 있는 트리 영역입니다.</p><ul><li><strong>[대행사 추가] 버튼</strong>: 상단 <code>+</code> 버튼으로 신규 대행사 등록</li><li><strong>대행사 아이템</strong>: <ul><li>직영/외주 배지 표출</li><li>수정, 삭제, 하위 팀 추가 버튼 제공</li></ul></li><li><strong>하위 팀 아이템</strong>: <ul><li>팀 소속 인원수 배지 표출</li><li>클릭 시 해당 팀이 강조 표시되며 우측 인력 명부가 자동 필터링</li><li>수정 및 삭제 버튼 제공</li></ul></li></ul><h3 id="_2-우측-영업-인력-명부" tabindex="-1">2. 우측 영업 인력 명부 <a class="header-anchor" href="#_2-우측-영업-인력-명부" aria-label="Permalink to &quot;2. 우측 영업 인력 명부&quot;">​</a></h3><p>선택된 대행사 또는 팀에 소속된 영업 인력의 상세 명단 테이블입니다.</p><ul><li><strong>상단 필터 및 제어 바</strong>: <ul><li>직책 필터 (전체, 분양상담사, 팀장, 본부장, 총괄본부장, 지원/기타)</li><li>재직 상태 필터 (전체, 재직, 휴직, 해촉)</li><li>성명/연락처/예금주 검색창</li><li><strong><code>[신규 인력 등록]</code></strong> 버튼</li></ul></li><li><strong>인력 목록 테이블</strong>: <ul><li>소속 대행사 및 팀</li><li>직책 배지 (상담사, 팀장, 본부장, 총괄)</li><li>성명 (클릭 시 수정 팝업 호출)</li><li>연락처 및 소득 구분 (3.3% 프리랜서 배지)</li><li>정산 계좌 정보 (은행명, 계좌번호, 예금주)</li><li><strong>제출 서류 배지</strong>: 제출된 서류 건수 배지 표출 (<code>[📎 서류 N건]</code>), 클릭 시 전용 서류 관리 팝업 호출</li><li>재직 상태 배지 (재직, 휴직, 해촉)</li><li>관리 액션: 수정 및 삭제 버튼</li></ul></li></ul><h3 id="_3-입력-팝업-안내" tabindex="-1">3. 입력 팝업 안내 <a class="header-anchor" href="#_3-입력-팝업-안내" aria-label="Permalink to &quot;3. 입력 팝업 안내&quot;">​</a></h3><h4 id="_1-대행사-등록-팝업" tabindex="-1">① 대행사 등록 팝업 <a class="header-anchor" href="#_1-대행사-등록-팝업" aria-label="Permalink to &quot;① 대행사 등록 팝업&quot;">​</a></h4><ul><li><strong>대행사명</strong> (필수): 회사 상호 또는 직영 사업단 명칭</li><li><strong>운영 형태</strong>: <code>직영 분양팀</code> 또는 <code>외주 대행사</code> 선택</li><li><strong>대표자명 / 사업자등록번호 / 연락처 / 담당자 정보</strong></li><li><strong>계약 기간</strong>: 대행 계약 시작일 및 종료일</li></ul><h4 id="_2-영업-팀-등록-팝업" tabindex="-1">② 영업 팀 등록 팝업 <a class="header-anchor" href="#_2-영업-팀-등록-팝업" aria-label="Permalink to &quot;② 영업 팀 등록 팝업&quot;">​</a></h4><ul><li><strong>소속 대행사</strong> (필수): 소속될 상위 대행사 선택</li><li><strong>상위 조직</strong>: 본부 산하 팀 구성 시 상위 본부 선택 (다단계 계층 지원)</li><li><strong>팀/조직명</strong> (필수): 예: &quot;분양 1본부&quot;, &quot;영업 2팀&quot;</li><li><strong>팀장 성명</strong>: 조직 책임자 성명</li></ul><h4 id="_3-영업-인력-등록-수정-팝업" tabindex="-1">③ 영업 인력 등록/수정 팝업 <a class="header-anchor" href="#_3-영업-인력-등록-수정-팝업" aria-label="Permalink to &quot;③ 영업 인력 등록/수정 팝업&quot;">​</a></h4><ul><li><strong>소속 팀</strong> (필수): 배치될 영업 팀 선택</li><li><strong>성명</strong> (필수) 및 <strong>직책</strong> (상담사, 팀장, 본부장, 총괄본부장, 지원/기타)</li><li><strong>휴대전화</strong> (필수) 및 <strong>주민등록번호</strong> (원천세 신고 식별용)</li><li><strong>소득 구분</strong> (필수): <code>3.3% 사업소득 (프리랜서)</code>, <code>근로소득</code>, <code>사업자 (세금계산서)</code>, <code>기타</code></li><li><strong>정산 계좌 정보</strong>: 거래 은행 선택, 계좌번호, 예금주명</li><li><strong>증빙 서류 관리 바로가기</strong>: 기존 인력 수정 모드 시 하단에 증빙 서류 현황 및 바로가기 버튼 제공</li><li><strong>활동 및 재직 정보</strong>: 재직 상태, 위촉/입사일자 및 해촉/퇴사일자</li><li><strong>비고 / 특이사항</strong>: 추천인, 영업 경력 사항 등 메모</li></ul><h3 id="_4-증빙-서류-접수-및-검증-팝업" tabindex="-1">4. 증빙 서류 접수 및 검증 팝업 <a class="header-anchor" href="#_4-증빙-서류-접수-및-검증-팝업" aria-label="Permalink to &quot;4. 증빙 서류 접수 및 검증 팝업&quot;">​</a></h3><p>영업 인력이 영업 활동 및 수수료 정산을 위해 제출한 각종 증빙 서류를 업로드하고 검증하는 전용 창입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">서류 구분</th><th style="text-align:center;">권장/필수 여부</th><th style="text-align:left;">세부 내용 및 활용처</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>주민등록등본/초본</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">본인 실명 확인 및 주소지 확인 (원천징수 영수증 발급용)</td></tr><tr><td style="text-align:left;"><strong>통장 사본 (계좌 사본)</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">수수료 정산 이체 시 명의 일치 확인</td></tr><tr><td style="text-align:left;"><strong>신분증 사본</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">주민등록번호 확인 및 신원 보증</td></tr><tr><td style="text-align:left;"><strong>영업 위촉계약서</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">분양 대행 수수료 지급 및 위촉 효력 입증 서류</td></tr><tr><td style="text-align:left;"><strong>각종 서약서/각서</strong></td><td style="text-align:center;">선택/권장</td><td style="text-align:left;">보안/비밀유지 서약서, 청렴이행각서 등</td></tr><tr><td style="text-align:left;"><strong>기타 증빙서류</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">사업자등록증 사본, 공인중개사 자격증 등</td></tr></tbody></table><ul><li><strong>신규 서류 업로드</strong>: <ul><li>서류 구분 선택 후 PDF, JPG, PNG 파일 선택하여 등록</li></ul></li><li><strong>제출 서류 관리</strong>: <ul><li><strong>다운로드 / 열람</strong>: 파일명 클릭 시 새 창에서 즉시 원본 열람 및 다운로드</li><li><strong>관리자 검증</strong>: 서류 대조 후 <strong><code>[검증]</code></strong> 버튼 클릭 시 <code>검증완료</code> 상태로 변경되며 검증자 및 일시 기록 (필요 시 <code>[검증취소]</code> 가능)</li><li><strong>서류 삭제</strong>: 잘못 접수된 서류는 즉시 삭제 처리</li></ul></li></ul><h3 id="_5-모바일-앱-환경-서류-열람-및-공유" tabindex="-1">5. 모바일 앱 환경 서류 열람 및 공유 <a class="header-anchor" href="#_5-모바일-앱-환경-서류-열람-및-공유" aria-label="Permalink to &quot;5. 모바일 앱 환경 서류 열람 및 공유&quot;">​</a></h3><p>현장 관리자나 대행사 관계자가 스마트폰 모바일 환경에서도 상담사의 제출 서류를 즉시 확인하고 공유할 수 있습니다.</p><ul><li><strong>서류 요약 카드</strong>: 인력 카드에서 제출 서류 건수와 검증 통계(전체/검증완료/확인대기) 한눈에 파악</li><li><strong>원클릭 열람</strong>: 모바일 화면에서 터치 즉시 PDF 뷰어 또는 이미지 뷰어로 서류 확인</li><li><strong>원터치 공유</strong>: 모바일 공유 기능을 통해 카카오톡, 이메일로 세무사나 본사 담당자에게 다이렉트 전송</li><li><strong>현장 검증 지원</strong>: 현장 실사 후 모바일 화면에서 직접 <code>[검증]</code> 처리 가능</li></ul><h2 id="_4-신입사원을-위한-실무-가이드" tabindex="-1">4. 신입사원을 위한 실무 가이드 <a class="header-anchor" href="#_4-신입사원을-위한-실무-가이드" aria-label="Permalink to &quot;4. 신입사원을 위한 실무 가이드&quot;">​</a></h2><ul><li><strong>💡 신규 상담사 투입 시 필수 4대 서류 체크리스트</strong>: <ul><li>상담사가 현장에 투입되면 첫 수수료 정산일 전까지 반드시 <strong>[주민등록등본, 통장 사본, 신분증 사본, 위촉계약서]</strong> 4종을 제출받아 시스템에 등록하십시오. 서류가 미비하거나 예금주명이 일치하지 않으면 수수료 지급이 보류될 수 있습니다.</li></ul></li><li><strong>💡 상담사 퇴사(해촉) 처리 요령</strong>: <ul><li>상담사가 현장을 떠날 때는 프로필을 삭제하지 말고 <strong>재직 상태를 &#39;해촉&#39;으로 변경</strong>하십시오. 그래야 과거에 체결한 분양 계약 실적과 기정산된 수수료 이력이 안전하게 보존됩니다.</li></ul></li></ul>',28))])}const f=e(B,[["render",C]]);export{x as __pageData,f as default};
